package si.spindl.manufacturing;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import si.spindl.identity.TenantAuditEventEntity;
import si.spindl.identity.TenantAuditEventRepository;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;
@Service
public class WorkCenterService {
    private final WorkCenterRepository centers;private final WorkOrderOperationRepository operations;private final WorkOrderRepository workOrders;private final si.spindl.catalog.ItemRepository items;private final si.spindl.identity.TenantMembershipRepository memberships;private final si.spindl.identity.AppUserRepository users;private final TenantAuditEventRepository audit;
    public WorkCenterService(WorkCenterRepository centers,WorkOrderOperationRepository operations,WorkOrderRepository workOrders,si.spindl.catalog.ItemRepository items,si.spindl.identity.TenantMembershipRepository memberships,si.spindl.identity.AppUserRepository users,TenantAuditEventRepository audit){this.centers=centers;this.operations=operations;this.workOrders=workOrders;this.items=items;this.memberships=memberships;this.users=users;this.audit=audit;}
    @Transactional(readOnly=true) public List<ManufacturingDtos.WorkCenterView> list(UUID tenantId){return centers.findAllByTenantIdOrderByCode(tenantId).stream().map(this::view).toList();}
    @Transactional(readOnly=true) public List<ManufacturingDtos.OperatorOption> operators(UUID tenantId){return memberships.findAllByTenantIdAndRoleAndActiveTrueOrderByCreatedAtAsc(tenantId,"OPERATOR").stream().map(membership->users.findById(membership.getUserId()).orElseThrow()).map(user->new ManufacturingDtos.OperatorOption(user.getId(),user.getDisplayName(),user.getEmail())).toList();}
    @Transactional(readOnly=true) public List<ManufacturingDtos.WorkCenterQueueCard> queue(UUID tenantId,UUID centerId){centers.findByTenantIdAndId(tenantId,centerId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Work center not found"));return operations.findAllByTenantIdAndWorkCenterIdAndStatusInOrderBySequenceAsc(tenantId,centerId,List.of("PENDING","IN_PROGRESS")).stream().map(operation->{var order=workOrders.findById(operation.getWorkOrderId()).filter(candidate->candidate.getTenantId().equals(tenantId)&&List.of("RELEASED","IN_PROGRESS").contains(candidate.getStatus())).orElse(null);if(order==null)return null;var item=items.findByTenantIdAndId(tenantId,order.getFinishedItemId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Finished item not found"));return new ManufacturingDtos.WorkCenterQueueCard(operation.getId(),operation.getSequence(),operation.getName(),operation.getStatus(),operation.getOperatorUserId(),operation.getStartedAt(),order.getId(),order.getOrderNumber(),order.getStatus(),item.getSku(),item.getName(),order.getTargetQuantity(),order.getDueDate(),order.getPriority());}).filter(java.util.Objects::nonNull).toList();}
    @Transactional public ManufacturingDtos.WorkCenterView create(UUID tenantId,UUID actorId,ManufacturingDtos.WorkCenterRequest request){String code=request.code().trim().toUpperCase(Locale.ROOT);if(centers.existsByTenantIdAndCodeIgnoreCase(tenantId,code))throw new ResponseStatusException(HttpStatus.CONFLICT,"Work center code already exists");var center=centers.save(new WorkCenterEntity(tenantId,code,request.name().trim(),request.description()==null?null:request.description().trim(),request.laborRatePerHour(),request.overheadRatePerHour()));audit.save(new TenantAuditEventEntity(tenantId,actorId,"WORK_CENTER_CREATED","work_center",center.getId(),Map.of("code",code)));return view(center);}
    @Transactional public ManufacturingDtos.WorkCenterView setActive(UUID tenantId,UUID actorId,UUID id,boolean active){var center=centers.findByTenantIdAndId(tenantId,id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Work center not found"));center.setActive(active);audit.save(new TenantAuditEventEntity(tenantId,actorId,active?"WORK_CENTER_ACTIVATED":"WORK_CENTER_DEACTIVATED","work_center",id,Map.of()));return view(center);}
    private ManufacturingDtos.WorkCenterView view(WorkCenterEntity center){return new ManufacturingDtos.WorkCenterView(center.getId(),center.getCode(),center.getName(),center.getDescription(),center.isActive(),center.getLaborRatePerHour(),center.getOverheadRatePerHour());}
}
